window.RT_BOOKEND_CAPTIONS = {"course-intro-en":[{"start":0.0,"end":4.07,"text":"Expanding into the US market can\nunlock massive opportunity, but"},{"start":3.92,"end":6.63,"text":"it also comes with challenges\nthat catch many international"},{"start":6.48,"end":7.85,"text":"businesses off -guard."},{"start":8.2,"end":12.29,"text":"This roadmap is phase one of the\nUCF soft landing program, and it"},{"start":12.14,"end":15.05,"text":"is designed to help you avoid\nthose mistakes and move forward"},{"start":14.9,"end":15.9,"text":"with confidence."},{"start":16.04,"end":18.67,"text":"Over the next eight modules,\nwe'll travel through central"},{"start":18.52,"end":19.52,"text":"Florida together."},{"start":20.0,"end":22.49,"text":"Each destination on your\ndashboard covers a different"},{"start":22.34,"end":23.34,"text":"piece of the puzzle."},{"start":23.6,"end":26.93,"text":"From legal setup, to taxes, to\nUS business culture,"},{"start":27.26,"end":29.41,"text":"you can move at your own pace in\nany order."},{"start":29.26,"end":32.85,"text":"Each section includes practical\nguidance, tools and short"},{"start":32.7,"end":34.99,"text":"checkpoints to help you apply\nwhat you're learning."},{"start":35.4,"end":38.37,"text":"Use the language toggle at any\ntime to switch between English"},{"start":38.22,"end":39.22,"text":"and Spanish."},{"start":39.38,"end":43.01,"text":"One important note, this program\nprovides general guidance, not"},{"start":42.86,"end":44.85,"text":"legal, tax or immigration\nadvice."},{"start":45.1,"end":47.73,"text":"Always confirm the details with\na qualified professional."},{"start":48.2,"end":50.89,"text":"When you're ready, head back to\nyour dashboard and pick your"},{"start":50.74,"end":51.74,"text":"first destination."},{"start":52.06,"end":53.06,"text":"Let's get started."}],"course-intro-es":[{"start":0.0,"end":3.61,"text":"Expandirse al mercado de Estados\nUnidos puede abrir oportunidades"},{"start":3.46,"end":7.13,"text":"enormes, pero también viene con\ndesafíos que sorprenden a muchas"},{"start":6.98,"end":8.63,"text":"empresas internacionales."},{"start":8.72,"end":13.27,"text":"Esta hoja de ruta es la fase 1\ndel programa Soft Landing de UCF"},{"start":13.12,"end":16.89,"text":"y está diseñada para ayudarle a\nevitar esos errores y avanzar"},{"start":16.74,"end":17.74,"text":"con confianza."},{"start":18.06,"end":21.21,"text":"A lo largo de los próximos 8\nmódulos, recorreremos juntos"},{"start":21.06,"end":22.09,"text":"Florida Central."},{"start":22.38,"end":25.43,"text":"Cada destino en su panel cubre\nuna pieza diferente del"},{"start":25.28,"end":28.95,"text":"rompecabezas, desde la formación\nlegal, hasta los impuestos,"},{"start":29.22,"end":31.63,"text":"hasta la cultura empresarial\nestadounidense."},{"start":31.9,"end":34.93,"text":"Puede avanzar a su propio ritmo\nen cualquier orden."},{"start":35.34,"end":37.73,"text":"Cada sección incluye orientación\npráctica,"},{"start":38.06,"end":41.69,"text":"herramientas y puntos de control\ncortos para ayudarle a aplicar"},{"start":41.54,"end":42.79,"text":"lo que está aprendiendo."},{"start":43.16,"end":46.51,"text":"Use el selector de idioma en\ncualquier momento para cambiar"},{"start":46.36,"end":49.27,"text":"entre inglés y español, una nota\nimportante."},{"start":49.62,"end":53.47,"text":"Este programa proporciona\norientación general, no asesoría"},{"start":53.32,"end":55.71,"text":"legal, fiscal ni migratoria."},{"start":55.84,"end":58.95,"text":"Siempre confirme los detalles\ncon un profesional calificado."},{"start":59.18,"end":62.89,"text":"Cuando esté listo, regrese a su\npanel y elija su primer destino."},{"start":63.16,"end":64.16,"text":"Comencemos."}],"module-1-intro-en":[{"start":0.0,"end":3.25,"text":"Welcome to Downtown, where you\nbuild the foundation for your U"},{"start":3.1,"end":4.1,"text":".S."},{"start":3.24,"end":4.24,"text":"operations."},{"start":4.18,"end":6.71,"text":"The decisions you make here\ndon't just set things up."},{"start":6.78,"end":9.99,"text":"They lock in your tax structure,\naffect your visa options, and"},{"start":9.84,"end":11.05,"text":"determine whether U .S."},{"start":10.92,"end":12.13,"text":"investors can fund you."},{"start":12.36,"end":14.43,"text":"Get this right, and everything\nelse gets easier."},{"start":14.64,"end":16.69,"text":"Get it wrong, and it's expensive\nto fix."},{"start":16.96,"end":19.47,"text":"In this module, you'll make four\ncritical decisions."},{"start":19.82,"end":24.51,"text":"Choose the right entity, LLC, or\nC -Corp, and understand why an S"},{"start":24.36,"end":27.03,"text":"-Corp usually isn't an option\nfor international founders."},{"start":27.38,"end":30.07,"text":"Register your business in\nFlorida through Florida Division"},{"start":29.92,"end":30.92,"text":"of Corporations."},{"start":31.16,"end":33.59,"text":"Set up a registered agent, and\nobtain your EIN."},{"start":34.0,"end":36.31,"text":"Prepare what you actually need\nto open a U .S."},{"start":36.36,"end":37.36,"text":"business bank account."},{"start":37.44,"end":41.09,"text":"One key point, use the entity\ndecision guide before you speak"},{"start":40.94,"end":41.94,"text":"with an attorney."},{"start":41.94,"end":45.53,"text":"Not after, it will help you ask\nthe right questions and avoid"},{"start":45.38,"end":46.38,"text":"costly mistakes."},{"start":46.7,"end":47.7,"text":"Let's get to work."}],"module-1-intro-es":[{"start":0.0,"end":3.41,"text":"Bienvenido al Centro, donde\nconstruye la base para sus"},{"start":3.26,"end":5.41,"text":"operaciones en EEUU."},{"start":5.72,"end":8.87,"text":"Las decisiones que tome aquí no\nsolo configuran las cosas,"},{"start":9.18,"end":12.83,"text":"fijan su estructura fiscal,\nafectan sus opciones de visa y"},{"start":12.68,"end":15.77,"text":"determinan si los inversionistas\nestadounidenses pueden"},{"start":15.62,"end":16.62,"text":"financiarle."},{"start":16.74,"end":19.43,"text":"Hágalo bien y todo lo demás se\nvuelve más fácil."},{"start":19.62,"end":21.75,"text":"Hágalo mal y es costoso\ncorregirlo."},{"start":21.94,"end":25.11,"text":"En este módulo tomará cuatro\ndecisiones críticas."},{"start":24.96,"end":30.39,"text":"Elegir la entidad correcta, LLC\no C -Corp y comprender por qué"},{"start":30.24,"end":33.79,"text":"una S -Corp generalmente no es\nuna opción para fundadores"},{"start":33.64,"end":34.85,"text":"internacionales."},{"start":35.02,"end":38.01,"text":"Registrar su negocio en Florida\na través de la División de"},{"start":37.86,"end":39.15,"text":"Corporaciones de Florida."},{"start":39.44,"end":42.53,"text":"Establecer un agente registrado\ny obtener su EIN."},{"start":42.72,"end":45.63,"text":"Preparar lo que realmente\nnecesita para abrir una cuenta"},{"start":45.48,"end":49.61,"text":"bancaria comercial en EEUU, un\npunto clave."},{"start":49.9,"end":53.27,"text":"Use la guía de decisión de\nentidad antes de hablar con un"},{"start":53.12,"end":54.51,"text":"abogado, no después."},{"start":54.58,"end":58.09,"text":"Le ayudará a hacer las preguntas\ncorrectas y evitar errores"},{"start":57.94,"end":58.94,"text":"costosos."},{"start":58.82,"end":59.83,"text":"¡Manos a la obra!"}],"module-1-outro-en":[{"start":0.0,"end":1.93,"text":"You've completed the downtown\nmodule."},{"start":2.18,"end":4.33,"text":"Here's what matters most as you\nmove forward."},{"start":4.46,"end":6.37,"text":"Your entity type is the\nfoundation."},{"start":6.64,"end":9.99,"text":"It shapes tax structure, visas,\nand whether investors will"},{"start":9.84,"end":10.84,"text":"engage with you."},{"start":11.16,"end":14.81,"text":"Sunbiz registration itself is\nstraightforward, but the real"},{"start":14.66,"end":16.21,"text":"work happens before you file."},{"start":16.42,"end":18.73,"text":"Banking takes longer than\nfounders expect."},{"start":19.02,"end":22.17,"text":"Call ahead, bring complete\ndocuments, and use payment"},{"start":22.02,"end":23.35,"text":"processors as a bridge."},{"start":23.66,"end":26.55,"text":"When you're ready, head back to\nyour dashboard and pick whatever"},{"start":26.4,"end":28.37,"text":"destination you want to learn\nabout next."}],"module-1-outro-es":[{"start":0.0,"end":2.19,"text":"ha completado el módulo del\ncentro."},{"start":2.4,"end":5.07,"text":"Esto es lo más importante a\nmedida que avanza."},{"start":5.3,"end":9.17,"text":"Su tipo de entidad es la base,\ndefine la estructura fiscal,"},{"start":9.52,"end":13.19,"text":"las opciones de visa y si los\ninversionistas trabajarán con"},{"start":13.04,"end":14.04,"text":"usted."},{"start":13.7,"end":17.23,"text":"El registro en Zumbis en sí es\ndirecto, pero el verdadero"},{"start":17.08,"end":20.09,"text":"trabajo ocurre antes de\npresentar la solicitud."},{"start":20.26,"end":23.51,"text":"La parte bancaria toma más\ntiempo de lo que los fundadores"},{"start":23.36,"end":27.59,"text":"esperan, llame con anticipación,\ntraiga la documentación completa"},{"start":27.44,"end":30.35,"text":"y use procesadores de pago como\npuente."},{"start":30.52,"end":34.11,"text":"Cuando esté listo, regrese a su\npanel y elija el destino que"},{"start":33.96,"end":35.75,"text":"quiera explorar a continuación."}],"module-2-intro-en":[{"start":0.0,"end":1.67,"text":"Welcome to the financial\ndistrict."},{"start":1.74,"end":4.13,"text":"Florida's tax -friendly\nreputation is real."},{"start":4.46,"end":7.87,"text":"There's no state personal income\ntax, but that doesn't mean no"},{"start":7.72,"end":8.72,"text":"taxes."},{"start":8.52,"end":9.67,"text":"Federal taxes apply,"},{"start":9.98,"end":10.98,"text":"sales tax applies,"},{"start":11.3,"end":13.65,"text":"and the rules may look very\ndifferent from what you're used"},{"start":13.5,"end":14.5,"text":"to."},{"start":14.12,"end":17.23,"text":"In this module, you'll learn\nwhich federal, state, and local"},{"start":17.08,"end":20.81,"text":"taxes actually apply to you, and\nhow your entity choice changes"},{"start":20.66,"end":21.66,"text":"the outcome,"},{"start":21.76,"end":22.76,"text":"why U .S."},{"start":22.44,"end":25.77,"text":"sales tax works nothing like\nVAT, and what that means for"},{"start":25.62,"end":29.11,"text":"your pricing, what it takes to\nopen a business account, build U"},{"start":28.96,"end":29.96,"text":".S."},{"start":29.12,"end":30.93,"text":"credit, and move money\nefficiently."},{"start":31.3,"end":33.67,"text":"Take your time with the tax\ncomparison calculator."},{"start":34.06,"end":37.11,"text":"It's the fastest way to see what\nyour real obligations look like."},{"start":37.34,"end":38.34,"text":"Let's begin."}],"module-2-intro-es":[{"start":0.0,"end":2.37,"text":"Bienvenida al Distrito\nFinanciero."},{"start":2.68,"end":5.77,"text":"La reputación de Florida como\namigable con los impuestos es"},{"start":5.62,"end":8.89,"text":"real, no hay impuesto estatal\nsobre la renta personal."},{"start":9.28,"end":11.61,"text":"Pero eso no significa que no\nhaya impuestos."},{"start":11.96,"end":15.53,"text":"Los impuestos federales aplican,\nel impuesto sobre las ventas"},{"start":15.38,"end":19.29,"text":"aplica y las reglas pueden verse\nmuy diferentes de lo que está"},{"start":19.14,"end":20.14,"text":"acostumbrada."},{"start":20.14,"end":24.63,"text":"En este módulo, aprenderá qué\nimpuestos federales, estatales y"},{"start":24.48,"end":28.27,"text":"locales realmente le aplican y\ncómo su elección de entidad"},{"start":28.12,"end":29.43,"text":"cambia el resultado."},{"start":29.78,"end":34.43,"text":"¿Por qué el impuesto sobre las\nventas en EEUU funciona muy"},{"start":34.28,"end":37.69,"text":"diferente de Liba y qué\nsignifica eso para sus precios?"},{"start":38.06,"end":40.59,"text":"¿Qué se necesita para abrir una\ncuenta empresarial?"},{"start":40.82,"end":45.25,"text":"Construir crédito en EEUU y\nmover dinero de manera"},{"start":45.1,"end":46.1,"text":"eficiente."},{"start":46.34,"end":49.05,"text":"Tómese su tiempo con la\ncalculadora de comparación de"},{"start":48.9,"end":49.9,"text":"impuestos."},{"start":49.84,"end":53.19,"text":"Es la forma más rápida de ver\ncómo se ven sus obligaciones"},{"start":53.04,"end":54.04,"text":"reales."},{"start":53.98,"end":54.98,"text":"Comencemos."}],"module-2-outro-en":[{"start":0.0,"end":2.97,"text":"That's the financial district,\nwhere assumptions get replaced"},{"start":2.82,"end":3.82,"text":"with clarity."},{"start":3.8,"end":4.8,"text":"Remember,"},{"start":4.52,"end":8.17,"text":"no state income tax doesn't mean\nno taxes, federal, quarterly"},{"start":8.02,"end":10.67,"text":"estimates and self -employment\ntax still apply."},{"start":11.04,"end":12.04,"text":"U .S."},{"start":11.44,"end":14.51,"text":"sales tax is state by state,\nregister with the Florida"},{"start":14.36,"end":17.75,"text":"Department of Revenue before\ncollecting sales tax in Florida."},{"start":18.06,"end":19.57,"text":"Banking is a preparation game."},{"start":19.82,"end":22.35,"text":"Bring complete documents and\nstart building U .S."},{"start":22.22,"end":24.13,"text":"credit as soon as your account\nopens."},{"start":24.54,"end":27.21,"text":"When you're ready, head back to\nyour dashboard and choose your"},{"start":27.06,"end":28.06,"text":"next module."}],"module-2-outro-es":[{"start":0.0,"end":3.43,"text":"Ese es el distrito financiero\ndonde las suposiciones se"},{"start":3.28,"end":4.65,"text":"reemplazan con claridad."},{"start":4.8,"end":8.79,"text":"Recuerde, sin impuesto estatal\nsobre la renta no significa sin"},{"start":8.64,"end":12.51,"text":"impuestos, los federales, los\nestimados trimestrales y el"},{"start":12.36,"end":15.15,"text":"impuesto de trabajo por cuenta\npropia aún aplican."},{"start":15.34,"end":19.47,"text":"El impuesto sobre las ventas de\nEEUU es estado por estado."},{"start":19.64,"end":22.99,"text":"Regístrese con el Departamento\nde Ingresos de Florida antes de"},{"start":22.84,"end":24.93,"text":"cobrar impuestos sobre las\nventas en Florida."},{"start":25.3,"end":27.75,"text":"La parte bancaria es un juego de\npreparación."},{"start":27.6,"end":32.07,"text":"Traiga la documentación completa\ny empiece a construir crédito en"},{"start":31.92,"end":34.67,"text":"EEUU, tan pronto como abra su\ncuenta."},{"start":34.92,"end":38.89,"text":"Cuando esté lista, regrese a su\npanel y elija su próximo módulo."}],"module-3-intro-en":[{"start":0.0,"end":2.63,"text":"We're at the Space Center, like\na space launch."},{"start":2.82,"end":5.63,"text":"Your business needs the right\nprotections before it leaves the"},{"start":5.48,"end":6.48,"text":"pad."},{"start":6.16,"end":9.15,"text":"The most expensive mistakes here\nare the ones founders don't see"},{"start":9.0,"end":10.07,"text":"until it's too late."},{"start":10.18,"end":13.39,"text":"In this module, you'll make\nthree key protection decisions."},{"start":13.72,"end":17.03,"text":"Why your home country IP\nprotection does not cover you in"},{"start":16.88,"end":19.09,"text":"the US, and what to file first,"},{"start":19.42,"end":22.39,"text":"which insurance policies you\nneed from day one and which can"},{"start":22.24,"end":25.77,"text":"wait, when to handle legal work\nyourself, and when bringing in"},{"start":25.62,"end":27.31,"text":"an attorney can actually save\nyou money."},{"start":27.42,"end":31.31,"text":"If you take one thing from this\nmodule, file for US trademark"},{"start":31.16,"end":34.59,"text":"protection early, ideally before\nyou invest in marketing."},{"start":34.84,"end":35.84,"text":"Let's get into it."}],"module-3-intro-es":[{"start":0.0,"end":1.57,"text":"Estamos en el Centro Espacial."},{"start":1.8,"end":5.07,"text":"Como un lanzamiento espacial, su\nnegocio necesita las"},{"start":4.92,"end":7.31,"text":"protecciones correctas antes de\ndespegar."},{"start":7.54,"end":11.01,"text":"Los errores más costosos, aquí\nson los que los fundadores no"},{"start":10.86,"end":12.69,"text":"ven hasta que es demasiado\ntarde."},{"start":12.92,"end":16.39,"text":"En este módulo, tomará tres\ndecisiones clave de protección."},{"start":16.7,"end":19.59,"text":"¿Por qué la protección de\npropiedad intelectual de su país"},{"start":19.44,"end":22.91,"text":"de origen no le cubre en EEU y\nqué presentar primero?"},{"start":23.26,"end":27.03,"text":"¿Qué pólizas de seguro necesita\ndesde el primer día y cuáles"},{"start":26.88,"end":27.88,"text":"pueden esperar,"},{"start":28.04,"end":31.87,"text":"cuándo manejar el trabajo legal\nusted mismo y cuándo traer a un"},{"start":31.72,"end":34.05,"text":"abogado realmente puede\nahorrarle dinero?"},{"start":34.3,"end":37.45,"text":"Si se lleva una sola cosa de\neste módulo, presente la"},{"start":37.3,"end":41.91,"text":"protección de marca registrada\nde EEU U temprano, idealmente"},{"start":41.76,"end":43.35,"text":"antes de invertir en marketing."},{"start":43.76,"end":44.76,"text":"Manos a la obra."}],"module-3-outro-en":[{"start":0.0,"end":2.85,"text":"You've completed the space\ncenter, what matters moving"},{"start":2.7,"end":3.7,"text":"forward."},{"start":3.66,"end":5.09,"text":"IP is territorial."},{"start":5.52,"end":9.29,"text":"File your US trademark with the\nUSPTO before you launch in the"},{"start":9.14,"end":10.14,"text":"market."},{"start":9.96,"end":12.23,"text":"General liability insurance is\nthe baseline."},{"start":12.74,"end":15.49,"text":"Many clients and landlords\nrequire proof before they'll"},{"start":15.34,"end":16.34,"text":"work with you."},{"start":16.24,"end":19.97,"text":"Use free resources and referrals\nto get oriented, then engage a"},{"start":19.82,"end":22.63,"text":"qualified attorney for decisions\nthat carry legal risk."},{"start":22.74,"end":25.37,"text":"When you're ready, head back to\nyour dashboard and pick your"},{"start":25.22,"end":26.22,"text":"next destination."}],"module-3-outro-es":[{"start":0.0,"end":2.03,"text":"Ha completado el centro\nespacial."},{"start":2.24,"end":4.09,"text":"Esto es lo que importa al\navanzar."},{"start":4.24,"end":7.77,"text":"La propiedad intelectual es\nterritorial, presente su marca"},{"start":7.62,"end":12.37,"text":"registrada de EEUU, con la USPTO\nantes de lanzar en el mercado."},{"start":12.6,"end":15.71,"text":"El Seguro de Responsabilidad\nCivil General es la base."},{"start":15.94,"end":18.99,"text":"Muchos clientes y arrendadores\nrequieren prueba antes de"},{"start":18.84,"end":19.84,"text":"trabajar con usted."},{"start":19.96,"end":23.05,"text":"Use recursos gratuitos y\nreferidos para orientarse."},{"start":23.2,"end":26.63,"text":"Luego, contrate a un abogado\ncalificado para decisiones que"},{"start":26.48,"end":27.85,"text":"conllevan riesgo legal."},{"start":27.7,"end":31.55,"text":"Cuando esté listo, regrese a su\npanel y elija su próximo"},{"start":31.4,"end":32.4,"text":"destino."}],"module-4-intro-en":[{"start":0.0,"end":1.67,"text":"Welcome to the theme park\ndistrict."},{"start":1.92,"end":5.33,"text":"Great businesses are powered by\na strong team, but hiring in the"},{"start":5.18,"end":8.51,"text":"US comes with rules that often\nsurprise international founders,"},{"start":8.66,"end":11.35,"text":"and mistakes here can be\nexpensive and hard to resolve."},{"start":11.66,"end":14.77,"text":"In this module, you'll learn the\ndifference between an employee"},{"start":14.62,"end":15.67,"text":"and a contractor,"},{"start":16.04,"end":20.01,"text":"and how the IRS evaluates the\nactual working relationship, not"},{"start":19.86,"end":21.27,"text":"just what your contract says,"},{"start":21.6,"end":23.03,"text":"common US visa categories,"},{"start":23.38,"end":26.39,"text":"and why forming a company does\nnot automatically give you work"},{"start":26.24,"end":27.24,"text":"authorization."},{"start":26.76,"end":31.83,"text":"The true cost of hiring in the\nUS, salary plus roughly 15 -30 %"},{"start":31.68,"end":33.55,"text":"in additional employment costs."},{"start":33.84,"end":35.99,"text":"Spend some time with the hiring\ncost calculator."},{"start":36.34,"end":38.55,"text":"It will save you from\nunderestimating your first"},{"start":38.4,"end":39.4,"text":"payroll."},{"start":39.2,"end":40.2,"text":"Let's begin."}],"module-4-intro-es":[{"start":0.0,"end":2.47,"text":"Bienvenida al distrito de los\nparques temáticos."},{"start":2.8,"end":5.51,"text":"Los grandes negocios funcionan\ncon un equipo fuerte."},{"start":5.9,"end":9.61,"text":"Pero la contratación en EEUU\nviene con reglas que a menudo"},{"start":9.46,"end":12.79,"text":"sorprenden a los fundadores\ninternacionales y los errores"},{"start":12.64,"end":15.49,"text":"aquí pueden ser costosos y\ndifíciles de resolver."},{"start":15.74,"end":17.33,"text":"En este módulo aprenderá."},{"start":17.58,"end":21.43,"text":"La diferencia entre un empleado\ny un contratista, y cómo el IRS"},{"start":21.28,"end":25.25,"text":"evalúa la relación laboral real\nno solo lo que dice su contrato."},{"start":25.62,"end":29.85,"text":"Categorías comunes de visas en\nEEUU y por qué formar una"},{"start":29.7,"end":32.93,"text":"empresa no le da automáticamente\nautorización de trabajo."},{"start":33.24,"end":38.03,"text":"El costo real de contratar en\nEEUU salario más aproximadamente"},{"start":37.88,"end":41.55,"text":"15 a 30 % en costos adicionales\nde empleo."},{"start":41.82,"end":44.67,"text":"Pase tiempo con la calculadora\nde costos de contratación."},{"start":45.12,"end":47.35,"text":"Le evitará subestimar su primera\nnómina."},{"start":47.56,"end":48.56,"text":"Comencemos."}],"module-4-outro-en":[{"start":0.0,"end":1.75,"text":"You've completed the theme park\ndistrict."},{"start":2.16,"end":3.16,"text":"What to take with you?"},{"start":3.3,"end":5.97,"text":"Miss -classifying a worker as a\ncontractor when they should be"},{"start":5.82,"end":9.01,"text":"an employee can create tax,\ncompliance, and legal issues."},{"start":9.22,"end":10.57,"text":"Get clarity before you hire."},{"start":10.86,"end":13.99,"text":"Your visa status determines what\nyou can and cannot do in your"},{"start":13.84,"end":14.84,"text":"own company."},{"start":14.66,"end":16.29,"text":"Talk to an immigration attorney\nearly."},{"start":16.6,"end":21.45,"text":"Plan for total employment cost\nat roughly 1 .15 to 1 .30 times"},{"start":21.3,"end":22.3,"text":"base salary."},{"start":22.5,"end":25.55,"text":"When you're ready, head back to\nyour dashboard and pick the next"},{"start":25.4,"end":26.67,"text":"destination to explore."}],"module-4-outro-es":[{"start":0.0,"end":2.81,"text":"Ha completado el distrito de los\nparques temáticos."},{"start":3.14,"end":4.14,"text":"¿Qué llevarse?"},{"start":4.16,"end":7.79,"text":"Clasificar incorrectamente a un\ntrabajador como contratista"},{"start":7.64,"end":11.03,"text":"cuando debería ser empleado\npuede crear problemas fiscales,"},{"start":11.12,"end":14.35,"text":"de cumplimiento ilegales,\nobtenga claridad antes de"},{"start":14.2,"end":15.2,"text":"contratar."},{"start":15.1,"end":18.77,"text":"Su estatus migratorio determina\nqué puede y qué no puede hacer"},{"start":18.62,"end":19.75,"text":"en su propia empresa."},{"start":20.04,"end":22.33,"text":"Hable temprano con un abogado de\ninmigración."},{"start":22.52,"end":26.47,"text":"Planifique para un costo total\nde empleo de aproximadamente 1"},{"start":26.32,"end":29.09,"text":",15 a 1 ,30 veces el salario\nbase."},{"start":28.94,"end":30.33,"text":"Cuando esté lista,"},{"start":30.64,"end":34.19,"text":"regrese a su panel y elija el\npróximo destino a explorar."}],"module-5-intro-en":[{"start":0.0,"end":2.69,"text":"We've reached the harbor just\nlike the goods moving through a"},{"start":2.54,"end":3.54,"text":"port."},{"start":3.2,"end":5.21,"text":"Your product needs to be ready\nfor the U .S."},{"start":5.08,"end":6.39,"text":"market before it arrives."},{"start":6.78,"end":9.67,"text":"What worked in your home market\nwon't always work the same way."},{"start":9.88,"end":12.73,"text":"Here in this module, you'll\nlearn the key areas where"},{"start":12.58,"end":15.15,"text":"international products typically\nneed adaptation,"},{"start":15.62,"end":18.53,"text":"pricing, positioning,\ncompliance, support, and"},{"start":18.38,"end":19.38,"text":"payments."},{"start":19.2,"end":20.2,"text":"How U .S."},{"start":19.8,"end":23.93,"text":"buyers actually find, compare,\nand decide, and why speed and"},{"start":23.78,"end":26.29,"text":"responsiveness strongly\ninfluence conversion."},{"start":26.14,"end":27.39,"text":"What U .S."},{"start":27.34,"end":29.23,"text":"companies require before they\ncan pay you?"},{"start":29.36,"end":32.63,"text":"W9 forms, insurance\ncertificates, and vendor"},{"start":32.48,"end":33.48,"text":"onboarding."},{"start":33.56,"end":35.89,"text":"Pay close attention to the\npricing scenarios."},{"start":36.28,"end":39.63,"text":"Pricing that feels safe or\nfamiliar can still reduce"},{"start":39.48,"end":40.69,"text":"conversion in the U .S."},{"start":40.7,"end":41.7,"text":"market."},{"start":41.14,"end":42.14,"text":"Let's get to it."}],"module-5-intro-es":[{"start":0.0,"end":1.47,"text":"Hemos llegado al puerto."},{"start":1.64,"end":5.05,"text":"Al igual que las mercancías que\npasan por un puerto, su producto"},{"start":4.9,"end":8.75,"text":"necesita estar listo para el\nmercado estadounidense antes de"},{"start":8.6,"end":9.6,"text":"llegar."},{"start":9.3,"end":12.51,"text":"Lo que funcionó en su mercado de\norigen no siempre funcionará"},{"start":12.36,"end":13.36,"text":"igual aquí."},{"start":13.34,"end":17.09,"text":"En este módulo aprenderá las\náreas clave donde los productos"},{"start":16.94,"end":20.91,"text":"internacionales típicamente\nnecesitan adaptación, precios,"},{"start":21.06,"end":22.06,"text":"posicionamiento,"},{"start":22.2,"end":24.37,"text":"cumplimiento, soporte y pagos."},{"start":24.22,"end":27.13,"text":"¿Cómo los compradores\nestadounidenses realmente"},{"start":26.98,"end":29.37,"text":"encuentran, comparan y deciden?"},{"start":29.62,"end":32.97,"text":"¿Y por qué la velocidad y la\ncapacidad de respuesta influyen"},{"start":32.82,"end":34.57,"text":"fuertemente en la conversión?"},{"start":34.86,"end":39.75,"text":"¿Qué requieren las empresas de\nEEUU antes de poder pagarle?"},{"start":39.86,"end":44.11,"text":"¿Formularios W9, certificados de\nseguro e incorporación de"},{"start":43.96,"end":44.96,"text":"proveedores?"},{"start":45.04,"end":47.51,"text":"Preste mucha atención a los\nescenarios de precios."},{"start":47.64,"end":51.41,"text":"Un precio que se siente seguro o\nfamiliar todavía puede reducir"},{"start":51.26,"end":53.91,"text":"la conversión en el mercado\nestadounidense."},{"start":54.06,"end":55.11,"text":"Manos a la obra."}],"module-5-outro-en":[{"start":0.0,"end":1.19,"text":"You've completed the harbor."},{"start":1.48,"end":2.97,"text":"A few things to carry forward."},{"start":3.2,"end":6.61,"text":"US buyers often interpret\nunusually low pricing as lower"},{"start":6.46,"end":7.46,"text":"quality."},{"start":7.34,"end":10.03,"text":"Stay within the competitive\nrange and differentiate on"},{"start":9.88,"end":10.88,"text":"value."},{"start":10.66,"end":12.79,"text":"Speed is a trust signal in US\nsales."},{"start":13.06,"end":16.33,"text":"Same day responses are often the\nexpectation, not the exception."},{"start":16.54,"end":19.17,"text":"Vendor onboarding can delay\npayment for weeks."},{"start":19.38,"end":23.43,"text":"Prepare your W9 insurance and\nbanking details before you start"},{"start":23.28,"end":24.28,"text":"selling."},{"start":24.02,"end":26.83,"text":"When you're ready, head back to\nyour dashboard and pick the"},{"start":26.68,"end":28.27,"text":"topic you want to explore next."}],"module-5-outro-es":[{"start":0.0,"end":1.45,"text":"Ha completado el puerto."},{"start":1.58,"end":2.91,"text":"Algunas cosas para llevar."},{"start":3.12,"end":6.69,"text":"Los compradores estadounidenses\na menudo interpretan precios"},{"start":6.54,"end":9.07,"text":"inusualmente bajos como menor\ncalidad."},{"start":9.38,"end":12.71,"text":"Manténgase dentro del rango\ncompetitivo y diferencia por"},{"start":12.56,"end":13.56,"text":"valor."},{"start":13.28,"end":17.27,"text":"La velocidad es una señal de\nconfianza en las ventas en EEUU."},{"start":17.5,"end":21.11,"text":"Las respuestas el mismo día a\nmenudo son la expectativa, no la"},{"start":20.96,"end":21.96,"text":"excepción."},{"start":21.76,"end":25.05,"text":"La incorporación como proveedor\npuede retrasar el pago por"},{"start":24.9,"end":25.9,"text":"semanas."},{"start":25.6,"end":29.55,"text":"Prepáres su W9, Seguro y\ndetalles bancarios antes de"},{"start":29.4,"end":30.4,"text":"comenzar a vender."},{"start":30.54,"end":34.31,"text":"Cuando esté listo, regrese a su\npanel y elija el tema que quiera"},{"start":34.16,"end":35.53,"text":"explorar a continuación."}],"module-6-intro-en":[{"start":0.0,"end":1.0,"text":"We're at the beach."},{"start":1.12,"end":3.75,"text":"US business culture looks casual\non the surface."},{"start":4.02,"end":7.43,"text":"First names, coffee meetings,\nrelaxed dress code, but"},{"start":7.28,"end":11.13,"text":"underneath expectations are high\nand the signals aren't always"},{"start":10.98,"end":11.98,"text":"obvious."},{"start":11.8,"end":14.91,"text":"In this module, you'll learn the\ndifference between American"},{"start":14.76,"end":18.19,"text":"friendliness and real business\nintent and how to recognize the"},{"start":18.04,"end":19.04,"text":"difference,"},{"start":18.86,"end":22.19,"text":"how US meetings actually work\nand what effective follow -up"},{"start":22.04,"end":24.87,"text":"looks like, the cultural\nmissteps that quietly break"},{"start":24.72,"end":26.51,"text":"deals and how to avoid them."},{"start":26.8,"end":29.85,"text":"If you've ever had a great\nmeeting in the US, go cold"},{"start":29.7,"end":30.79,"text":"without explanation."},{"start":31.04,"end":32.73,"text":"This will help you understand\nwhy."},{"start":33.12,"end":34.12,"text":"Let's begin."}],"module-6-intro-es":[{"start":0.0,"end":1.51,"text":"Estamos en la playa."},{"start":1.66,"end":4.59,"text":"La cultura empresarial\nestadounidense parece informal"},{"start":4.44,"end":8.23,"text":"en la superficie Nombres de\npila, reuniones tomando café,"},{"start":8.54,"end":10.35,"text":"código de vestimenta relajado,"},{"start":10.82,"end":15.01,"text":"pero por debajo las expectativas\nson altas y las señales no"},{"start":14.86,"end":16.37,"text":"siempre son evidentes."},{"start":16.78,"end":20.75,"text":"En este módulo aprenderá la\ndiferencia entre la amabilidad"},{"start":20.6,"end":24.63,"text":"estadounidense y la intención\ncomercial real y cómo reconocer"},{"start":24.48,"end":25.48,"text":"la diferencia,"},{"start":25.64,"end":30.13,"text":"cómo funcionan realmente las\nreuniones en EEUU y cómo se ve"},{"start":29.98,"end":31.33,"text":"un seguimiento efectivo,"},{"start":31.66,"end":35.05,"text":"los errores culturales que\nsilenciosamente rompen acuerdos"},{"start":34.9,"end":36.33,"text":"y cómo evitarlos."},{"start":36.68,"end":40.93,"text":"Si alguna vez ha tenido una\nexcelente reunión en EEUU que es"},{"start":40.78,"end":44.53,"text":"en frío sin explicación, esto le\nayudará a entender por qué."},{"start":44.86,"end":45.86,"text":"Comencemos."}],"module-6-outro-en":[{"start":0.0,"end":1.59,"text":"You've completed the beach\nmodule."},{"start":2.12,"end":3.21,"text":"A few things to remember."},{"start":3.56,"end":5.35,"text":"A friendly meeting is not a\nclosed deal."},{"start":5.52,"end":8.01,"text":"Look for clear, written\nconfirmation before you spend"},{"start":7.86,"end":8.86,"text":"money."},{"start":8.76,"end":11.75,"text":"In US business, trust is built\nthrough follow -through as much"},{"start":11.6,"end":12.6,"text":"as relationships."},{"start":12.86,"end":14.57,"text":"Speed signals professionalism."},{"start":14.66,"end":17.49,"text":"Sending a recap within 24 hours\nis a common expectation."},{"start":18.08,"end":20.61,"text":"When you're ready, head back to\nyour dashboard and explore"},{"start":20.46,"end":21.46,"text":"another destination."}],"module-6-outro-es":[{"start":0.0,"end":3.53,"text":"Ha completado el módulo de la\nplaya, algunas cosas para"},{"start":3.38,"end":7.99,"text":"recordar, una reunión amigable\nno es un acuerdo cerrado, busque"},{"start":7.84,"end":11.41,"text":"confirmación clara y por escrito\nantes de gastar dinero."},{"start":11.92,"end":15.81,"text":"En los negocios estadounidenses,\nla confianza se construye tanto"},{"start":15.66,"end":18.07,"text":"a través del seguimiento como de\nlas relaciones."},{"start":18.5,"end":21.91,"text":"La velocidad es señal de\nprofesionalismo, enviar un"},{"start":21.76,"end":25.77,"text":"resumen dentro de 24 horas es\nuna expectativa común."},{"start":26.18,"end":27.23,"text":"Cuando esté lista,"},{"start":27.56,"end":30.59,"text":"regrese a su panel y explore\notro destino."}],"module-7-intro-en":[{"start":0.0,"end":1.53,"text":"Welcome to the Natural Springs."},{"start":1.88,"end":5.15,"text":"The Springs feed everything\ndownstream, and this module is"},{"start":5.0,"end":7.55,"text":"about the ecosystem that can\nfeed your business."},{"start":7.96,"end":10.89,"text":"Central Florida offers a deep\nnetwork of free founder"},{"start":10.74,"end":13.79,"text":"resources, and many\ninternational founders never"},{"start":13.64,"end":14.85,"text":"fully tap into it."},{"start":14.98,"end":18.59,"text":"In this module, you'll learn the\nfree resources available to you,"},{"start":18.76,"end":19.76,"text":"SBDC,"},{"start":19.92,"end":23.57,"text":"SCORE, the Orlando Economic\nPartnership, and the UCF"},{"start":23.42,"end":25.01,"text":"Business Incubation Program."},{"start":25.34,"end":28.03,"text":"What makes the Central Florida\necosystem different,"},{"start":28.08,"end":29.08,"text":"accessibility,"},{"start":28.98,"end":30.21,"text":"cost, and connectivity?"},{"start":30.62,"end":33.91,"text":"The factors that directly impact\nyour runway, and how this region"},{"start":33.76,"end":36.57,"text":"compares to Miami, New York, and\nSilicon Valley."},{"start":36.8,"end":39.99,"text":"Many founders pay for guidance\nthat is available for free."},{"start":40.26,"end":42.29,"text":"This module shows you where to\nlook first."},{"start":42.58,"end":43.58,"text":"Let's get into it."}],"module-7-intro-es":[{"start":0.0,"end":1.83,"text":"Bienvenido a los manantiales."},{"start":1.96,"end":5.59,"text":"Los manantiales alimentan todo\nlo que está río abajo y este"},{"start":5.44,"end":9.13,"text":"módulo trata sobre el ecosistema\nque puede alimentar su negocio."},{"start":9.4,"end":13.25,"text":"Florida Central ofrece una red\nprofunda de recursos gratuitos"},{"start":13.1,"end":16.81,"text":"para fundadores y muchos\nfundadores internacionales nunca"},{"start":16.66,"end":18.25,"text":"la aprovechan por completo."},{"start":18.52,"end":22.37,"text":"En este módulo aprenderá los\nrecursos gratuitos disponibles"},{"start":22.22,"end":26.79,"text":"para usted, SBDC, SCORE, la\nOrlando Economic Partnership y"},{"start":26.64,"end":30.19,"text":"el Programa de Incubación de\nEmpresas de UCF, que hace"},{"start":30.04,"end":32.33,"text":"diferente al ecosistema de\nFlorida Central,"},{"start":32.64,"end":35.07,"text":"accesibilidad, costo y\nconectividad."},{"start":35.32,"end":38.73,"text":"Los factores que impactan\ndirectamente su runway y cómo se"},{"start":38.58,"end":42.05,"text":"compara esta región con Miami,\nNueva York y Silicon Valley."},{"start":42.28,"end":45.71,"text":"Muchos fundadores pagan por\norientación que está disponible"},{"start":45.56,"end":46.56,"text":"gratis."},{"start":46.32,"end":50.13,"text":"Este módulo le muestra dónde\nbuscar primero, manos a la obra."}],"module-7-outro-en":[{"start":0.0,"end":3.35,"text":"You've completed the Natural\nSprings, your support network."},{"start":3.68,"end":7.75,"text":"The SBDC at UCF offers free\nongoing business consulting."},{"start":8.14,"end":11.31,"text":"Use it early to validate\ndecisions before paying for"},{"start":11.16,"end":12.16,"text":"private services."},{"start":12.62,"end":15.61,"text":"Lower operating costs in central\nFlorida can extend your runway"},{"start":15.46,"end":16.46,"text":"by months."},{"start":16.56,"end":18.93,"text":"That's often the difference\nbetween reaching product market"},{"start":18.78,"end":20.09,"text":"fit and running out of cash."},{"start":20.54,"end":23.21,"text":"Founders who succeed here\nactively use the ecosystem."},{"start":23.7,"end":27.79,"text":"Advisors, mentors, and partner\norganizations to move faster and"},{"start":27.64,"end":29.01,"text":"avoid costly mistakes."},{"start":29.28,"end":32.19,"text":"When you're ready, head back to\nyour dashboard and choose what"},{"start":32.04,"end":33.04,"text":"to explore next."}],"module-7-outro-es":[{"start":0.0,"end":1.93,"text":"ha completado los manantiales."},{"start":2.06,"end":7.03,"text":"Su red de apoyo, el SBDC en UCF,\nofrece consultoría empresarial"},{"start":6.88,"end":10.69,"text":"gratuita y continua, use la\ntemprano para validar decisiones"},{"start":10.54,"end":12.73,"text":"antes de pagar por servicios\nprivados."},{"start":12.98,"end":16.69,"text":"Costos operativos más bajos en\nFlorida Central pueden extender"},{"start":16.54,"end":20.53,"text":"su runway por meses, esa suele\nser la diferencia entre alcanzar"},{"start":20.38,"end":23.15,"text":"el ajuste producto mercado y\nquedarse sin dinero."},{"start":23.4,"end":26.75,"text":"Los fundadores que tienen éxito\naquí usan activamente el"},{"start":26.6,"end":30.61,"text":"ecosistema, asesores, mentores y\norganizaciones aliadas para"},{"start":30.46,"end":33.51,"text":"avanzar más rápido y evitar\nerrores costosos."},{"start":33.76,"end":37.51,"text":"Cuando esté listo, regrese a su\npanel y elija que explorar a"},{"start":37.36,"end":38.36,"text":"continuación."}],"module-8-intro-en":[{"start":0.0,"end":3.49,"text":"Welcome to UCF campus, the final\nstop before you take action."},{"start":3.8,"end":6.69,"text":"You've worked through every\nmajor area of US market entry."},{"start":6.98,"end":9.51,"text":"Now it's time to decide what\nyou're ready to do and what"},{"start":9.36,"end":10.37,"text":"needs attention first."},{"start":10.96,"end":14.25,"text":"In this module, you'll complete\na structured self -assessment"},{"start":14.1,"end":15.63,"text":"across all core topics."},{"start":15.98,"end":19.03,"text":"Identify your highest priority\ngaps and where to get the right"},{"start":18.88,"end":19.88,"text":"support."},{"start":19.68,"end":22.47,"text":"Download the resources that turn\nwhat you've learned into an"},{"start":22.32,"end":23.32,"text":"action plan."},{"start":23.48,"end":26.49,"text":"This isn't a test, it's a\ndecision tool to help you choose"},{"start":26.34,"end":27.49,"text":"what comes next."},{"start":27.72,"end":28.93,"text":"Let's take the next step."}],"module-8-intro-es":[{"start":0.0,"end":4.57,"text":"Bienvenida al Campus UCF, la\nparada final antes de actuar."},{"start":4.82,"end":7.93,"text":"Ha recorrido cada área\nimportante de la entrada al"},{"start":7.78,"end":9.25,"text":"mercado estadounidense."},{"start":9.56,"end":13.35,"text":"Ahora es el momento de decidir\nqué está lista para hacer y qué"},{"start":13.2,"end":14.61,"text":"necesita atención primero."},{"start":14.9,"end":18.67,"text":"En este módulo, completará una\nautoevaluación estructurada en"},{"start":18.52,"end":19.85,"text":"todos los temas clave."},{"start":20.32,"end":23.81,"text":"Identificará sus brechas de\nmayor prioridad y dónde obtener"},{"start":23.66,"end":24.71,"text":"el apoyo adecuado."},{"start":25.02,"end":28.13,"text":"Descargará los recursos que\nconvierten lo que ha aprendido"},{"start":27.98,"end":29.11,"text":"en un plan de acción."},{"start":28.96,"end":30.95,"text":"Esto no es un examen."},{"start":31.08,"end":34.87,"text":"Es una herramienta de decisión\npara ayudarle a elegir qué viene"},{"start":34.72,"end":35.72,"text":"después."},{"start":35.66,"end":36.91,"text":"Demos el siguiente paso."}],"module-8-outro-en":[{"start":0.0,"end":1.51,"text":"You've reached the end of the\nroadmap."},{"start":1.9,"end":3.57,"text":"This is where the execution\nbegins."},{"start":4.14,"end":5.25,"text":"What matters most now?"},{"start":5.48,"end":6.67,"text":"Progress comes from action."},{"start":6.9,"end":8.47,"text":"Use what you've learned to move\nforward."},{"start":8.84,"end":11.45,"text":"Your lowest self -assessment\nscores define your highest"},{"start":11.3,"end":12.71,"text":"priority next steps."},{"start":12.84,"end":15.97,"text":"Book your one -on -one with the\nUCF Business Incubation Program"},{"start":15.82,"end":16.82,"text":"team."},{"start":16.54,"end":19.01,"text":"This is where your plan becomes\nspecific and actionable."},{"start":19.34,"end":22.13,"text":"Thank you for completing the US\nMarket Readiness Program."},{"start":22.48,"end":25.29,"text":"The next step is yours, and feel\nfree to come back to your"},{"start":25.14,"end":27.19,"text":"dashboard when you need to\nrevisit a topic."}],"module-8-outro-es":[{"start":0.0,"end":1.99,"text":"Ha llegado al final de la hoja\nde ruta."},{"start":2.14,"end":4.15,"text":"Aquí es donde comienza la\nejecución."},{"start":4.46,"end":7.69,"text":"Lo que más importa ahora, el\nprogreso viene de la acción."},{"start":7.96,"end":9.95,"text":"Use lo que ha aprendido para\navanzar."},{"start":10.14,"end":13.35,"text":"Sus puntajes más bajos en la\nautoevaluación definen sus"},{"start":13.2,"end":15.13,"text":"próximos pasos de mayor\nprioridad."},{"start":15.36,"end":18.55,"text":"Reserve su sesión personalizada\ncon el equipo del programa de"},{"start":18.4,"end":20.29,"text":"incubación de empresas de UCF."},{"start":20.44,"end":23.39,"text":"Aquí es donde su plan se vuelve\nespecífico y accionable."},{"start":23.74,"end":26.59,"text":"Gracias por completar el\nprograma de preparación para el"},{"start":26.44,"end":27.79,"text":"mercado de Estados Unidos."},{"start":28.07,"end":31.49,"text":"El siguiente paso es suyo y\nsientas el libre de regresar a"},{"start":31.34,"end":33.53,"text":"su panel cuando necesite revisar\nun tema."}]};
